export function filterMedicalAidProviders(
  query: string = '',
  category: string = 'all'
): MedicalAidProvider[] {
  const cleanQ = query.trim().toLowerCase();
  const cleanCat = category.trim().toLowerCase();

  return medicalAidProviders.filter((p) => {
    if (cleanCat !== 'all' && p.category !== cleanCat) {
      return false;
    }
    if (!cleanQ) return true;
    return (
      p.name.toLowerCase().includes(cleanQ) ||
      p.schemeType.toLowerCase().includes(cleanQ) ||
      p.categoryLabel.toLowerCase().includes(cleanQ) ||
      p.websiteUrl.toLowerCase().includes(cleanQ)
    );
  });
}
